// The preview-image chain of a content item (spec 06 FR-086/FR-087, BR-046): which
// picture represents an item when it is shared, and where its crawler-safe 1200×630
// JPEG derivative lives. Pure; the derivatives are generated by services/og-image.ts.

/** Name of a media derivative: `<uuid>.jpg`; brand derivatives are `brand-<hex>.jpg`. */
export const OG_NAME_PATTERN = /^([0-9a-f-]{36}|brand-[0-9a-f]{6})\.jpg$/
/** An upload the derivative can be built from (every media upload is `<uuid>.webp`). */
const UPLOAD_PATTERN = /^\/uploads\/([0-9a-f-]{36})\.webp$/
/** Brand background when a link has no site (or the site accent is not a hex colour). */
export const NEUTRAL_ACCENT = '111111'

/**
 * Field selection (README → Fixed contracts (a)): Card → `data.thumbnail`, Poster →
 * `data.imageUrl`, other types → null. `data` is locale-merged, so a locale override
 * wins over the base image. Only uploaded media (`/uploads/…`) qualify.
 */
export function itemImageUrl(type: string, data: Record<string, unknown>): string | null {
  const field = type === 'card' ? data.thumbnail : type === 'poster' ? data.imageUrl : null
  return typeof field === 'string' && field.startsWith('/uploads/') ? field : null
}

/** '/uploads/<uuid>.webp' → '/uploads/og/<uuid>.jpg'; null for anything else. */
export function ogDerivativePath(uploadUrl: string): string | null {
  const match = UPLOAD_PATTERN.exec(uploadUrl)
  return match ? `/uploads/og/${match[1]}.jpg` : null
}

/** '#3B82F6' / '#38f' → '3b82f6'; anything else → the neutral colour. */
export function accentHex(accent: string | null | undefined): string {
  const raw = (accent ?? '').trim().replace(/^#/, '').toLowerCase()
  if (/^[0-9a-f]{6}$/.test(raw)) return raw
  if (/^[0-9a-f]{3}$/.test(raw)) return raw.split('').map(ch => ch + ch).join('')
  return NEUTRAL_ACCENT
}

/** Brand derivative of a site accent (null → hub brand): '/uploads/og/brand-111111.jpg'. */
export function brandDerivativePath(accent: string | null): string {
  return `/uploads/og/brand-${accentHex(accent)}.jpg`
}
